#!/usr/bin/env python3
"""Fail when fleet digest/calendar build outputs are tracked on main.

After AFC-690 / AFC-736, published snapshots live on branch
``published/fleet-activity`` (and GitHub Pages deploys from workflow
artifacts).  These paths must not be committed on ``main`` again.
"""

from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path

DEFAULT_ROOT = Path(__file__).resolve().parent.parent

# Generated by build-agent-calendar.py / build-fleet-daily-digest.py — not source.
FORBIDDEN_TRACKED: tuple[str, ...] = (
    "site/index.html",
    "site/digest.md",
    "calendar/daily-digest.ics",
    "calendar/agent-activity.ics",
)

FORBIDDEN_PREFIXES: tuple[str, ...] = ("site/calendar/",)


def tracked_files(root: Path) -> list[str]:
    done = subprocess.run(
        ["git", "-C", str(root), "ls-files", "-z"],
        capture_output=True,
        check=False,
        timeout=60,
    )
    if done.returncode != 0:
        raise RuntimeError(done.stderr.decode(errors="replace").strip() or "git ls-files failed")
    return [p for p in done.stdout.decode("utf-8", "surrogateescape").split("\0") if p]


def forbidden_on_main(root: Path) -> list[str]:
    offenders: list[str] = []
    for path in tracked_files(root):
        if path in FORBIDDEN_TRACKED:
            offenders.append(path)
            continue
        for prefix in FORBIDDEN_PREFIXES:
            if path.startswith(prefix):
                offenders.append(path)
                break
    return sorted(offenders)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument(
        "--root",
        type=Path,
        default=DEFAULT_ROOT,
        help="repository checkout to inspect (default: this repo)",
    )
    args = ap.parse_args(argv)
    try:
        offenders = forbidden_on_main(args.root)
    except RuntimeError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    if offenders:
        for path in offenders:
            print(
                f"error: {path}: fleet activity artifact must not be tracked on main "
                "(publish to published/fleet-activity instead)"
            )
        return 1
    print("ok: no fleet activity build outputs tracked on main")
    return 0


if __name__ == "__main__":
    sys.exit(main())
